<?php
declare(strict_types=1);
require __DIR__.'/../../apps/local-web/src/Core/Migrations.php';
require __DIR__.'/../../apps/local-web/src/Core/MigrationExecutionException.php';
use Sokna\Local\Core\Migrations;
$pdo=new PDO('mysql:host=127.0.0.1;port=3306;dbname=sokna_r138_ci;charset=utf8mb4','root','ci-root-only',[
  PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION, PDO::ATTR_EMULATE_PREPARES=>false]);
foreach(['schema_migration_statements','schema_migrations','cafe_ddl_checkpoint','test_items','test_users','remote_user_credentials','guard_flags'] as $name)
    $pdo->exec('DROP TABLE IF EXISTS `'.$name.'`');
$pdo->exec('CREATE TABLE test_items(item_code VARCHAR(40) PRIMARY KEY,qty INT NOT NULL) ENGINE=InnoDB');
$pdo->exec("INSERT INTO test_items(item_code,qty) VALUES('already',10)");
$pdo->exec('CREATE TABLE test_users(username VARCHAR(60) PRIMARY KEY,password_hash VARCHAR(200) NOT NULL) ENGINE=InnoDB');
$pdo->exec("INSERT INTO test_users(username,password_hash) VALUES('worker','before-hash')");
$pdo->exec('CREATE TABLE remote_user_credentials(username VARCHAR(60) PRIMARY KEY,password_hash VARCHAR(200) NOT NULL) ENGINE=InnoDB');
$pdo->exec('CREATE TABLE guard_flags(flag VARCHAR(32) PRIMARY KEY,allowed TINYINT NOT NULL) ENGINE=InnoDB');
$pdo->exec("INSERT INTO guard_flags(flag,allowed) VALUES('tea_pre',1),('tea_post',0),('staff_pre',1),('staff_post',0)");
$directory=sys_get_temp_dir().'/sokna-r138-'.bin2hex(random_bytes(6));
mkdir($directory,0700,true);
$guard=static fn(string $key):string=>"SELECT (SELECT x FROM (SELECT 1 x UNION ALL SELECT 2 x) fail WHERE EXISTS (SELECT 1 FROM guard_flags WHERE flag='$key' AND allowed=0));\n";
file_put_contents($directory.'/0077_disposable_ddl.sql',"CREATE TABLE IF NOT EXISTS cafe_ddl_checkpoint(id INT PRIMARY KEY) ENGINE=InnoDB;\n");
file_put_contents($directory.'/0078_disposable_catalog.sql',$guard('tea_pre')."INSERT INTO test_items(item_code,qty) VALUES('tea',3);\nUPDATE test_items SET qty=qty+1 WHERE item_code='already';\n".$guard('tea_post'));
file_put_contents($directory.'/0079_disposable_staff.sql',$guard('staff_pre')."UPDATE test_users SET password_hash='after-hash' WHERE username='worker';\nINSERT INTO remote_user_credentials(username,password_hash) VALUES('worker','remote-after');\n".$guard('staff_post'));
$m=new Migrations($pdo,$directory);
$assert=static function(bool $ok,string $msg):void {if(!$ok)throw new RuntimeException('FAIL '.$msg);echo 'PASS '.$msg.PHP_EOL;};
$count=static fn(string $table):int=>(int)$pdo->query('SELECT COUNT(*) FROM '.$table)->fetchColumn();
$val=static fn(string $sql):string=>(string)$pdo->query($sql)->fetchColumn();
$throws=static function(callable $fn,string $msg)use($assert):void {$caught=false;try{$fn();}catch(Throwable){$caught=true;}$assert($caught,$msg);};
$throws(fn()=>$m->migrate(),'post-DML tea guard failed safely');
$assert($count('schema_migrations')===1 && $count('schema_migration_statements')===1,'DDL committed; 0078 data and journal rolled back');
$assert($count('test_items')===1 && $val("SELECT qty FROM test_items WHERE item_code='already'")==='10','no partial business DML after guard failure');
$pdo->exec("UPDATE guard_flags SET allowed=1 WHERE flag='tea_post'");
$throws(fn()=>$m->migrate(),'post-DML staff guard failed safely');
$assert($count('schema_migrations')===2 && $count('remote_user_credentials')===0,'0078 committed, 0079 rolled back entirely');
$assert($val("SELECT password_hash FROM test_users WHERE username='worker'")==='before-hash','existing staff credentials preserved on failed migration');
$assert((int)$pdo->query("SELECT COUNT(*) FROM schema_migration_statements WHERE version='0079_disposable_staff'")->fetchColumn()===0,'0079 failed journal has no RUNNING residual');
$pdo->exec("UPDATE guard_flags SET allowed=1 WHERE flag='staff_post'");
$assert($m->migrate()===['0079_disposable_staff'],'exact forward resume succeeded');
$assert($val("SELECT password_hash FROM test_users WHERE username='worker'")==='after-hash' && $count('remote_user_credentials')===1,'staff local+remote credentials committed atomically');
$assert($m->migrate()===[],'idempotent replay did not reset staff data');
$assert((int)$pdo->query("SELECT COUNT(*) FROM schema_migration_statements WHERE state='running'")->fetchColumn()===0,'no stranded RUNNING migration journal');
$bad=sys_get_temp_dir().'/sokna-r138-bad-'.bin2hex(random_bytes(6));mkdir($bad,0700,true);
file_put_contents($bad.'/0078_mixed_ddl.sql',"UPDATE test_items SET qty=555 WHERE item_code='already'; CREATE TABLE forbidden_ddl(id INT) ENGINE=InnoDB;");
$throws(fn()=>(new Migrations($pdo,$bad))->migrate(),'DDL disguised as 0078 data migration rejected');
$assert($val("SELECT qty FROM test_items WHERE item_code='already'")==='11','DDL rejection occurred before data mutation');
$pdo->exec('CREATE TABLE test_myisam(id INT) ENGINE=MyISAM');
$bad2=sys_get_temp_dir().'/sokna-r138-myisam-'.bin2hex(random_bytes(6));mkdir($bad2,0700,true);
file_put_contents($bad2.'/0078_nontransactional.sql',"UPDATE test_items SET qty=999 WHERE item_code='already';");
$throws(fn()=>(new Migrations($pdo,$bad2))->migrate(),'non-InnoDB data schema rejected before mutation');
$pdo->exec('DROP TABLE test_myisam');
$assert($val("SELECT qty FROM test_items WHERE item_code='already'")==='11','MyISAM preflight kept business rows unchanged');
echo "R138_MARIADB_ATOMIC_0078_0079_AND_FORWARD_RESUME_PASS\n";
